CREATE TABLE IF NOT EXISTS disposiciones_registros(id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT NOT NULL UNIQUE,oficina TEXT NOT NULL,estado TEXT NOT NULL,matricula TEXT NOT NULL,nombre TEXT NOT NULL,fecha_recepcion TEXT NOT NULL,fecha_gestion TEXT NOT NULL,datos TEXT NOT NULL,persona TEXT NOT NULL,busqueda TEXT NOT NULL,duplicate_key TEXT NOT NULL UNIQUE,creation_hash TEXT NOT NULL,creator TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS disposiciones_oficina ON disposiciones_registros(oficina,estado,fecha_recepcion,id);
CREATE INDEX IF NOT EXISTS disposiciones_matricula ON disposiciones_registros(matricula,id);
CREATE TABLE IF NOT EXISTS disposiciones_eventos(id TEXT PRIMARY KEY,registro TEXT NOT NULL REFERENCES disposiciones_registros(uuid),fecha_gestion TEXT NOT NULL,accion TEXT NOT NULL,actor TEXT NOT NULL,nombre_actor TEXT NOT NULL,motivo TEXT NOT NULL,datos TEXT NOT NULL,persona TEXT NOT NULL,version INTEGER NOT NULL,request_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,creado TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS disposiciones_evento_periodo ON disposiciones_eventos(fecha_gestion,registro,creado);
CREATE TABLE IF NOT EXISTS disposiciones_informes(id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT NOT NULL UNIQUE,quincena TEXT NOT NULL,hash TEXT NOT NULL UNIQUE,payload TEXT NOT NULL,actor TEXT NOT NULL,creado TEXT NOT NULL);
